/// Scans the next token, if any.
fn scan(&mut self) -> Option<Token> {
    self.skip_whitespace();
    if self.chars.peek().is_none() {
        return None;
    }
    if let Some(t) = self.scan_ident_quoted().ok().flatten() {
        return Some(t);
    }
    if let Some(t) = self.scan_ident_or_keyword() {
        return Some(t);
    }
    if let Some(t) = self.scan_number() {
        return Some(t);
    }
    if let Some(t) = self.scan_string().ok().flatten() {
        return Some(t);
    }
    if let Some(t) = self.scan_symbol() {
        return Some(t);
    }
    None
}
